<?php
declare(strict_types=1);
use Pivot\{Auth,AdminActions,Applications,Statistics,Exports,Queue,Bot};
ini_set('display_errors','0');
header('X-Content-Type-Options: nosniff'); header('X-Frame-Options: DENY'); header('Referrer-Policy: same-origin');
header("Content-Security-Policy: default-src 'none'; style-src 'self'; font-src 'self'; img-src 'self' data:; form-action 'self'; base-uri 'none'; frame-ancestors 'none'");
header('Cache-Control: no-store');
try { require (require __DIR__.'/paths.php').'/app/bootstrap.php'; }
catch(Throwable) { http_response_code(503); exit('Application configuration unavailable. Follow the private installation guide.'); }
Auth::session((bool)$config['session_secure']);
$auth=new Auth($db); $admin=$auth->current(); $page=(string)($_GET['page']??'dashboard'); $error='';
$e=Exports::escape(...);
function redirect(string $url): never { header('Location: '.$url,true,303); exit; }
function csrf(): string { return '<input type="hidden" name="csrf" value="'.htmlspecialchars($_SESSION['csrf'],ENT_QUOTES).'">'; }
function action(string $action,?int $id=null): string { return csrf().'<input type="hidden" name="action" value="'.htmlspecialchars($action,ENT_QUOTES).'">'.($id!==null?'<input type="hidden" name="id" value="'.$id.'">':''); }
function badge(string $status): string { return '<span class="badge badge-'.str_replace(' ','-',$status).'">'.htmlspecialchars($status,ENT_QUOTES).'</span>'; }
if($_SERVER['REQUEST_METHOD']==='POST') {
    if(!Auth::csrf((string)($_POST['csrf']??''))) { http_response_code(403); exit('Invalid CSRF token'); }
    try {
        if(($_POST['action']??'')==='login') {
            if($auth->login((string)($_POST['email']??''),(string)($_POST['password']??''),$_SERVER['REMOTE_ADDR']??'unknown')) redirect('?page=dashboard');
            $error='Login failed or rate limit reached. Try again later.';
        } elseif(!$admin) { http_response_code(401); exit('Login required'); }
        elseif(($_POST['action']??'')==='logout') { Auth::logout(); redirect('?page=login'); }
        else {
            $db->pdo->beginTransaction();
            $next=(new AdminActions($db,new Queue($db,$telegram)))->perform($admin,$_POST);
            $db->pdo->commit(); $_SESSION['flash']='Changes saved.'; redirect($next);
        }
    } catch(DomainException $ex) { if($db->pdo->inTransaction()) $db->pdo->rollBack(); http_response_code(403); $error=$ex->getMessage(); }
    catch(InvalidArgumentException $ex) { if($db->pdo->inTransaction()) $db->pdo->rollBack(); http_response_code(422); $error=$ex->getMessage(); }
    catch(Throwable $ex) { if($db->pdo->inTransaction()) $db->pdo->rollBack(); http_response_code(500); error_log('Pivot admin action failed: '.get_class($ex)); $error='Could not save. Check for duplicate email or database availability.'; }
}
if(!$admin && $page!=='login') {
    if(in_array($page,['export','download'],true)) { http_response_code(401); exit('Login required'); }
    redirect('?page=login');
}
if($admin && in_array($page,['settings','team'],true) && $admin['role']!=='owner') { http_response_code(403); exit('Owner access required'); }
$apps=new Applications($db);
try {
    if($admin && $page==='download') {
        $record=$db->one('SELECT * FROM applications WHERE id=?',[(int)($_GET['id']??0)]);
        if(!$record || !preg_match('/^[a-f0-9]{48}\.bin$/D',$record['file_key'])) { http_response_code(404); exit('File not found'); }
        $path=$config['storage'].'/private/'.$record['file_key']; if(!is_file($path)) { http_response_code(404); exit('File not found'); }
        $db->audit((int)$admin['id'],(int)$record['id'],'attachment_download','Original attachment');
        header('Content-Type: application/octet-stream'); header('Content-Length: '.filesize($path));
        header("Content-Disposition: attachment; filename=\"attachment.bin\"; filename*=UTF-8''".rawurlencode($record['file_name'])); readfile($path); exit;
    }
    if($admin && $page==='export') {
        $format=(string)($_GET['format']??'xlsx'); if(!in_array($format,['xlsx','pdf'],true)) throw new InvalidArgumentException('Invalid format');
        $statsOnly=($_GET['scope']??'')==='statistics'; $single=!empty($_GET['id']);
        if($single) { $row=$db->one('SELECT a.*,ad.email AS reviewer,(SELECT AVG(score) FROM ratings WHERE application_id=a.id) AS rating FROM applications a LEFT JOIN admins ad ON ad.id=a.assigned_to WHERE a.id=?',[(int)$_GET['id']]); if(!$row) { http_response_code(404); exit; } $rows=[$row]; }
        else { if(!$statsOnly && $apps->count($_GET)>($format==='pdf'?300:10000)) throw new InvalidArgumentException('Narrow the filters: maximum 300 applications per PDF or 10,000 per XLSX'); $rows=$statsOnly?[]:$apps->search($_GET,10000); }
        $stats=$statsOnly?(new Statistics($db))->report($_GET):null;
        $body=$format==='xlsx'?Exports::xlsx($rows,$stats):Exports::pdf($rows,$stats,$config['storage'].'/cache');
        $db->audit((int)$admin['id'],null,'export',$format.' '.count($rows).' applications; scope '.($statsOnly?'statistics':'applications'));
        header('Content-Type: '.($format==='xlsx'?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'application/pdf'));
        header('Content-Disposition: attachment; filename="pivot-'.($statsOnly?'statistics':'applications').'.'.$format.'"'); echo $body; exit;
    }
    Applications::range($_GET);
    if(!empty($_GET['status']) && !in_array($_GET['status'],Applications::STATUSES,true)) throw new InvalidArgumentException('Invalid status');
} catch(InvalidArgumentException $ex) { http_response_code(422); exit($e($ex->getMessage())); }
catch(Throwable $ex) { error_log('Pivot export/query failed: '.get_class($ex)); http_response_code(500); exit('Operation failed. Check private application logs.'); }
$flash=$_SESSION['flash']??''; unset($_SESSION['flash']);
$titles=['dashboard'=>'Overview','applications'=>'Applications','application'=>'Application review','statistics'=>'Statistics','queue'=>'Delivery queue','settings'=>'Event settings','team'=>'Team access','account'=>'Your account','login'=>'Sign in'];
$title=$titles[$page]??'Not found';
if(!isset($titles[$page])) http_response_code(404);
$selectedApplication=null;
if($page==='application') { $selectedApplication=$db->one('SELECT a.*,u.username FROM applications a JOIN users u ON u.id=a.user_id WHERE a.id=?',[(int)($_GET['id']??0)]); if(!$selectedApplication) http_response_code(404); }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $e($title) ?> · Pivot</title><link rel="stylesheet" href="assets/app.css"></head><body>
<?php if(!$admin): ?>
<main class="login-layout"><section class="login-story"><a class="brand" href="?">pivot<span>↗</span></a><div><p class="eyebrow">STARTUP GARAGE × YANDEX UZBEKISTAN</p><h1>Big ideas.<br>Next beginnings.</h1><p>The workspace for the people building what comes next.</p><div class="event-chip">GRAND DEMO DAY · 19 NOV 2026</div></div><small>Pivot Uzbekistan · Review workspace</small></section><section class="login-form"><div><p class="eyebrow">WELCOME BACK</p><h2>Sign in to Pivot</h2><p class="muted">Review applications. Support the next generation.</p><?php if($error): ?><p class="alert"><?= $e($error) ?></p><?php endif; ?><form method="post"><?= action('login') ?><label>Email address<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="primary wide">Sign in <span>↗</span></button></form><p class="muted small">Access is provided by your workspace owner.</p></div></section></main>
<?php else: ?>
