<main class="main"><header class="topbar"><span>Workspace <span class="muted">/ <?= $e($title) ?></span></span><span class="event-pill">● Grand Demo Day 2026</span></header><div class="content"><div class="page-heading"><div><p class="eyebrow">PIVOT UZBEKISTAN</p><h1><?= $e($title) ?></h1></div><span class="muted"><?= date('d M Y') ?> · Tashkent</span></div>
<?php if($error): ?><p class="alert"><?= $e($error) ?></p><?php endif; ?><?php if($flash): ?><p class="notice"><?= $e($flash) ?></p><?php endif; ?>
<?php if($page==='dashboard' || $page==='statistics'):
$stats=(new Statistics($db))->report($page==='statistics'?$_GET:[]); ?>
<?php if($page==='dashboard'): ?><section class="hero"><div><span class="eyebrow">THE NEXT WAVE STARTS HERE</span><h2>Good ideas deserve<br>a closer look.</h2><p>Grand Demo Day · 19 November · 14:00–18:00<br>Yandex Uzbekistan ofisi, Toshkent</p></div><a class="light-button" href="?page=applications">Review applications ↗</a></section><?php else: ?>
<form class="filters" method="get"><input type="hidden" name="page" value="statistics"><label>From<input type="date" name="from" value="<?= $e($_GET['from']??'') ?>"></label><label>Through<input type="date" name="to" value="<?= $e($_GET['to']??'') ?>"></label><button class="primary">Apply dates</button><a class="button" href="?page=statistics">All time</a></form>
